bool TaskManagerStubDispatch::Accept(
    TaskManager* impl,
    mojo::Message* message) {
  switch (message->header()->name) {
    case internal::kTaskManager_RegisterTaskManagerProvider_Name: {

      DCHECK(message->is_serialized());
      internal::TaskManager_RegisterTaskManagerProvider_Params_Data* params =
          reinterpret_cast<internal::TaskManager_RegisterTaskManagerProvider_Params_Data*>(
              message->mutable_payload());
      
      
      // Validation for TaskManager.0
      bool success = true;
      ::mojo::PendingRemote<TaskManagerProvider> p_provider{};
      ::base::UnguessableToken p_token{};
      TaskManager_RegisterTaskManagerProvider_ParamsDataView input_data_view(params, message);
      
      if (success) {
        p_provider =
            input_data_view.TakeProvider<decltype(p_provider)>();
      }
      if (success && !input_data_view.ReadToken(&p_token))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            TaskManager::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->RegisterTaskManagerProvider(        
        std::move(p_provider), 
        std::move(p_token));
      return true;
    }
    case internal::kTaskManager_ShowTaskManager_Name: {

      DCHECK(message->is_serialized());
      internal::TaskManager_ShowTaskManager_Params_Data* params =
          reinterpret_cast<internal::TaskManager_ShowTaskManager_Params_Data*>(
              message->mutable_payload());
      
      
      // Validation for TaskManager.1
      bool success = true;
      TaskManager_ShowTaskManager_ParamsDataView input_data_view(params, message);
      
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            TaskManager::Name_, 1, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->ShowTaskManager(        );
      return true;
    }
  }
  return false;
}

