void TaskManagerProviderAsyncWaiter::GetTaskManagerTasks(
    std::vector<TaskPtr>* out_task_results, std::vector<TaskGroupPtr>* out_task_group_results) {
  base::RunLoop loop;
  proxy_->GetTaskManagerTasks(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<TaskPtr>* out_task_results
,
             std::vector<TaskGroupPtr>* out_task_group_results
,
             std::vector<TaskPtr> task_results,
             std::vector<TaskGroupPtr> task_group_results) {*out_task_results = std::move(task_results);*out_task_group_results = std::move(task_group_results);
            loop->Quit();
          },
          &loop,
          out_task_results,
          out_task_group_results));
  loop.Run();
}






